// Parse the CSV from Google Sheets
const csvText = $('Fetch Google Sheet CSV').first().json.data || $('Fetch Google Sheet CSV').first().json.body;
const lines = csvText.trim().split('\n');
const headers = lines[0].split(',').map(h => h.trim());

const sheetPeople = [];
for (let i = 1; i < lines.length; i++) {
  const values = lines[i].split(',').map(v => v.trim());
  if (!values[1]) continue; // skip empty rows
  sheetPeople.push({
    name: values[1],
    title: values[2],
    team: values[3],
    email: values[4]
  });
}

// Get current org chart people
const orgData = $('Fetch Current Org Chart').first().json;
const orgPeople = Array.isArray(orgData) ? orgData : (orgData.body || []);
const orgNames = new Set(orgPeople.filter(p => p.isActive !== false).map(p => p.name.toLowerCase()));
const sheetNames = new Set(sheetPeople.map(p => p.name.toLowerCase()));

// Find differences
const newHires = sheetPeople.filter(p => !orgNames.has(p.name.toLowerCase()));
const departures = orgPeople.filter(p => p.isActive !== false && !sheetNames.has(p.name.toLowerCase()) && p.name !== 'Robbie Galoso');

// Find title/team changes
const titleChanges = [];
for (const sp of sheetPeople) {
  const match = orgPeople.find(op => op.name.toLowerCase() === sp.name.toLowerCase() && op.isActive !== false);
  if (match && match.title !== sp.title) {
    titleChanges.push({
      name: sp.name,
      oldTitle: match.title,
      newTitle: sp.title,
      oldDept: match.departmentName,
      newDept: sp.team
    });
  }
}

const totalChanges = newHires.length + departures.length + titleChanges.length;

let summary = `Org Chart Sync Report — ${new Date().toLocaleDateString()}\n`;
summary += `=======================================\n\n`;

if (totalChanges === 0) {
  summary += 'No changes detected. Org chart is up to date.';
} else {
  summary += `${totalChanges} change(s) detected:\n\n`;

  if (newHires.length > 0) {
    summary += `NEW HIRES (${newHires.length}):\n`;
    newHires.forEach(p => summary += `  + ${p.name} — ${p.title} (${p.team})\n`);
    summary += '\n';
  }

  if (departures.length > 0) {
    summary += `DEPARTURES (${departures.length}):\n`;
    departures.forEach(p => summary += `  - ${p.name} — ${p.title} (${p.departmentName})\n`);
    summary += '\n';
  }

  if (titleChanges.length > 0) {
    summary += `TITLE/ROLE CHANGES (${titleChanges.length}):\n`;
    titleChanges.forEach(c => summary += `  ~ ${c.name}: "${c.oldTitle}" → "${c.newTitle}"\n`);
    summary += '\n';
  }
}

return [{
  json: {
    totalChanges,
    summary,
    newHires,
    departures: departures.map(p => ({ name: p.name, title: p.title, dept: p.departmentName })),
    titleChanges,
    sheetPeopleCount: sheetPeople.length,
    orgPeopleActiveCount: orgPeople.filter(p => p.isActive !== false).length
  }
}];
